const $=(s,c=document)=>c.querySelector(s);const $$=(s,c=document)=>[...c.querySelectorAll(s)];
$('#year').textContent=new Date().getFullYear();
const menu=$('.menu-toggle'),nav=$('.nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Menüyü kapat':'Menüyü aç')});$$('.nav a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
$('.theme-toggle').addEventListener('click',()=>{document.body.classList.toggle('light-alt');localStorage.setItem('portfolio-theme',document.body.classList.contains('light-alt')?'alt':'default')});if(localStorage.getItem('portfolio-theme')==='alt')document.body.classList.add('light-alt');
const revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');revealObserver.unobserve(e.target)}}),{threshold:.12});$$('.reveal').forEach(el=>revealObserver.observe(el));
let counted=false;const metrics=$('.hero-metrics');if(metrics)new IntersectionObserver(([entry],o)=>{if(entry.isIntersecting&&!counted){counted=true;$$('[data-count]',metrics).forEach(el=>{const end=+el.dataset.count,start=performance.now(),duration=900;function step(t){const n=Math.min(1,(t-start)/duration);el.textContent=Math.floor(n*end);if(n<1)requestAnimationFrame(step);else el.textContent=end+'+'}requestAnimationFrame(step)});o.disconnect()}},{threshold:.4}).observe(metrics);
$$('.filter').forEach(button=>button.addEventListener('click',()=>{$$('.filter').forEach(b=>b.classList.remove('active'));button.classList.add('active');const filter=button.dataset.filter;$$('.project-card').forEach(card=>{card.hidden=filter!=='all'&&card.dataset.category!==filter})}));
$$('.timeline-item button').forEach(button=>button.addEventListener('click',()=>{const item=button.parentElement,wasActive=item.classList.contains('active');$$('.timeline-item').forEach(i=>i.classList.remove('active'));if(!wasActive)item.classList.add('active')}));
$$('.copy-code').forEach(button=>button.addEventListener('click',async()=>{const code=button.closest('.code-block').querySelector('code').innerText,old=button.textContent;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(code)}else{const area=document.createElement('textarea');area.value=code;area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();document.execCommand('copy');area.remove()}button.textContent='Kopyalandı';setTimeout(()=>button.textContent=old,1600)}catch{button.textContent='Seçip kopyalayın'}}));
